from .eth_interfaces import EthInterfaces


class ta5g_eth_interfaces(object):

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def get_eth_ip(self, eth_name, remote_host='127.0.0.1'):
        """
        Gets ip address of given eth interface
        :param eth_name: name of eth interface in form eth0, eth3 etc.
        :param remote_host: host IP of virtual machine from which get eth ip
        :return: ip of eth interface as string
        """
        return EthInterfaces.get_eth_ip(eth_name, remote_host)

    def get_hostname(self, remote_host='127.0.0.1'):
        """
        Gets hostname from given remote host virtual machine
        :param remote_host: virtual machines ip address
        :return: hostname as string
        """
        return EthInterfaces.get_hostname(remote_host)

    def get_eth_scope_global_ips(self, eth_name, remote_host='127.0.0.1'):
        """
        Gets ip address of given eth interface
        :param eth_name: name of eth interface in form eth0, eth3 etc.
        :param remote_host: host IP of virtual machine from which get eth ip
        :return: ip of eth interface as string
        """
        return EthInterfaces.get_eth_scope_global_ips(eth_name, remote_host)
